<?php
 namespace Pterodactyl\Services\Dezerx\DayZ; use Pterodactyl\Models\Server; use Pterodactyl\Models\EggVariable; use Pterodactyl\Services\Dezerx\ServerVariables; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; class DayZMods { public const CLIENT = 'MODIFICATIONS'; public const SERVER = 'SERVERMODS'; public const MOD_FILE = 'MOD_FILE'; public const NO_DOWNLOADS = 'DISABLE_MOD_UPDATES'; public const SIDES = ['client' => self::CLIENT, 'server' => self::SERVER]; private const FOLDER = '/^@[A-Za-z0-9][A-Za-z0-9_.\-]{0,63}$/'; private const MAX_ENTRIES = 120; private const MAX_KEY_BYTES = 65536; public static function parse(string $value): array { $out = []; $seen = []; foreach (explode(';', $value) as $raw) { $raw = trim($raw); if ($raw === '' || isset($seen[$raw])) { continue; } $seen[$raw] = true; $out[] = ['raw' => $raw, 'token' => preg_match(self::FOLDER, $raw) === 1 ? $raw : null]; } return $out; } public static function serialize(array $entries): string { return implode(';', array_map(fn (array $entry) => $entry['raw'], $entries)); } public static function folder(string $value): ?string { $value = trim($value); return preg_match(self::FOLDER, $value) === 1 ? $value : null; } public static function workshopId(string $folder): ?string { return preg_match('/^@([0-9]{1,20})$/', $folder, $match) === 1 ? $match[1] : null; } public static function definition(Server $server, string $key): ?EggVariable { return ServerVariables::definition($server, $key); } public static function editable(Server $server, string $key): bool { $variable = self::definition($server, $key); return $variable !== null && (bool) $variable->user_editable; } public static function entries(Server $server, string $key): array { return self::parse((string) (ServerVariables::value($server, $key) ?? '')); } public static function write(Server $server, string $key, array $entries): bool { if (!self::editable($server, $key) || count($entries) > self::MAX_ENTRIES) { return false; } return ServerVariables::set($server, $key, self::serialize($entries)); } public static function honoursOrder(Server $server, string $side): bool { if ($side === 'server') { return true; } $startup = (string) $server->startup; return !str_contains($startup, 'CLIENT_MODS') && str_contains($startup, 'MODIFICATIONS'); } public static function sortedOrder(array $entries): array { $raws = array_column(self::reachable($entries), 'raw'); sort($raws, SORT_STRING); return array_values(array_unique($raws)); } public static function reachable(array $entries): array { $out = []; foreach ($entries as $entry) { if (preg_match('/\s/', $entry['raw']) === 1) { break; } $out[] = $entry; } return $out; } public static function sideOf(Server $server, string $folder): ?string { foreach (self::SIDES as $side => $key) { foreach (self::entries($server, $key) as $entry) { if ($entry['raw'] === $folder) { return $side; } } } return null; } public static function modFileIds(ServerFiles $files, Server $server): array { $name = trim((string) (ServerVariables::value($server, self::MOD_FILE) ?? '')); if ($name === '' || str_contains($name, '..') || preg_match('~^[A-Za-z0-9_.\-/ ]{1,120}$~', $name) !== 1) { return []; } $html = $files->fileContents('/' . ltrim($name, '/'), 512000); if ($html === null || !str_contains($html, 'Created by DayZ Launcher')) { return []; } preg_match_all('~filedetails/\?id=([0-9]{1,20})~', $html, $matches); return array_values(array_unique($matches[1] ?? [])); } public static function folders(ServerFiles $files): ?array { $entries = $files->listFiles('/'); if ($entries === null) { return null; } $out = []; foreach ($entries as $entry) { $name = (string) $entry['name']; if ($entry['directory'] && str_starts_with($name, '@')) { $out[$name] = ['name' => $name, 'modifiedAt' => self::time($entry['modified_at'] ?? null)]; } } return $out; } public static function serverKeys(ServerFiles $files): array { $keys = []; foreach ($files->listFiles('/keys') ?? [] as $entry) { if (!$entry['directory'] && str_ends_with(mb_strtolower($entry['name']), '.bikey')) { $keys[mb_strtolower($entry['name'])] = true; } } return $keys; } public static function modKeys(ServerFiles $files, string $folder): array { $out = []; $present = []; foreach ($files->listFiles("/{$folder}") ?? [] as $entry) { if ($entry['directory'] && in_array(mb_strtolower($entry['name']), ['keys', 'key'], true)) { $present[] = $entry['name']; } } foreach ($present as $directory) { foreach ($files->listFiles("/{$folder}/{$directory}") ?? [] as $entry) { if (!$entry['directory'] && str_ends_with(mb_strtolower($entry['name']), '.bikey')) { $out[mb_strtolower($entry['name'])] = ['name' => $entry['name'], 'path' => "/{$folder}/{$directory}/{$entry['name']}"]; } } } return array_values($out); } public static function syncKeys(ServerFiles $files, string $folder): array { $have = self::serverKeys($files); $copied = []; foreach (self::modKeys($files, $folder) as $key) { if (isset($have[mb_strtolower($key['name'])]) || preg_match('/^[A-Za-z0-9_.\-]{1,96}\.bikey$/i', $key['name']) !== 1) { continue; } $contents = $files->fileContents($key['path'], self::MAX_KEY_BYTES); if ($contents === null || $contents === '') { continue; } $files->createDirectory('/keys'); if ($files->writeFile('/keys/' . $key['name'], $contents)) { $copied[] = $key['name']; $have[mb_strtolower($key['name'])] = true; } } return $copied; } public static function metaName(ServerFiles $files, string $folder): ?string { $meta = $files->fileContents("/{$folder}/meta.cpp", 8192); if ($meta !== null && preg_match('/^\s*name\s*=\s*"([^"\r\n]{1,100})"/mi', $meta, $match) === 1) { return trim($match[1]); } return null; } private static function time(mixed $value): ?int { if (!is_string($value) || $value === '') { return null; } $time = strtotime($value); return $time === false ? null : $time; } } 